n health benefits they are entitled to using federal benefits may give veterans more benefits save them money improve their health care and protect their family s assets 626 8th avenue southeast olympia thurston 98501 veterans benefit enhancement program veteran benefits assistance families veterans', 'hca.wa.gov', 0, 0, 'health-care-authority-veterans-benefit-enhancement-program-olympia-263f0b44');
INSERT INTO resources (id, name, category_id, subcategory, description, address, city, county, state, zip_code, phone, website, hours, accepts_uninsured, sliding_scale, medicaid, medicare, private_insurance, walk_ins_welcome, appointments, telehealth, cost_free, cost_estimate_min, cost_estimate_max, languages, accessibility, services, specialties, audiences, rating, photo_url, source, google_place_id, created_at, updated_at, tags, search_text, domain, lat, lng, slug) VALUES ('fc5d282d-d5c6-5c66-9798-dd5694c6ccad'::uuid, 'Intercity Transit - Dial-A-Lift', '499294fb-cf2a-46b3-ae6f-7d37d8939909'::uuid, 'Paratransit & Community Transportation', 'Provides a door-to-door, shared ride public transportation service for people with disabilities that prevent them from using the fixed route bus service. Passengers must complete an application, be eligible and certified to ride Dial-A-Lift. No cost to riders.', '510 Pattison Street Southeast', 'Olympia', 'Thurston', 'WA', '98501', '(360) 705-5896', 'https://www.intercitytransit.com/services/dial-lift', '{"monday":"closed","tuesday":"closed","wednesday":"closed","thursday":"closed","friday":"closed","saturday":"8:30am-11pm","sunday":"8:30am-8pm"}'::jsonb, false, false, false, false, false, false, false, false, true, 0, 0, ARRAY['English']::text[], ARRAY['interpreter services']::text[], ARRAY['Dial-A-Lift','Disability Related Transportation','General Paratransit/Community Ride Programs','Senior Ride Programs','Local Bus Transit Services']::text[], ARRAY['paratransit']::text[], ARRAY['Older Adults','People with disabilities']::text[], 4.5, '', 'https://search.wa211.org/search/fc5d282d-d5c6-5c66-9798-dd5694c6ccad', NULL, '2026-08-29 00:00:00+00', '2026-08-29 00:00:00+00', ARRAY['transportation','Paratransit & Community Transportation','Dial-A-Lift','Disability Related Transportation','General Paratransit/Community Ride Programs','Senior Ride Programs','Local Bus Transit Services','Thurston','Older Adults','People with disabilities'