INSERT INTO resources (id, name, category_id, subcategory, description, address, city, county, state, zip_code, phone, website, hours, accepts_uninsured, sliding_scale, medicaid, medicare, private_insurance, walk_ins_welcome, appointments, telehealth, cost_free, cost_estimate_min, cost_estimate_max, languages, accessibility, services, specialties, audiences, rating, photo_url, source, google_place_id, created_at, updated_at, tags, search_text, domain, lat, lng, slug) VALUES ('43b87cfc-ebec-5358-8fcb-c3bb2388fd5d'::uuid, 'Northwest Resources II West Olympia - Substance Use Disorder Treatment', 'aeeb251d-137d-476f-a8a2-b9482804a162'::uuid, 'Substance Use Treatment & Recovery', 'Program provides outpatient substance use disorder treatment services and intensive outpatient substance use disorder treatment for adults. Outpatient treatment services typically range from 3-20 hours per week of attendance, which may include individual and group counseling as well as support group meetings, relapse prevention, living skills and educational services. Also provides ADIS, DUI assessments and DUI Victims'' Panel.', '2708 Westmoor Court Southwest', 'Olympia', 'Thurston', 'WA', '98502', '(360) 943-8810', 'https://www.nwrii.com/', '{"monday":"8:30am-7pm. ADIS classes are Th 2nd Sa of each month. Victim''s Impact Panel offered on the 4th Saturday of each month","tuesday":"8:30am-7pm. ADIS classes are Th 2nd Sa of each month. Victim''s Impact Panel offered on the 4th Saturday of each month","wednesday":"8:30am-7pm. ADIS classes are Th 2nd Sa of each month. Victim''s Impact Panel offered on the 4th Saturday of each month","thursday":"8:30am-7pm. ADIS classes are Th 2nd Sa of each month. Victim''s Impact Panel offered on the 4th Saturday of each month","friday":"8:30am-7pm. ADIS classes are Th 2nd Sa of each month. Victim''s Impact Panel offered on the 4th Saturday of each month","saturday":"closed","sunday":"closed"}'::jsonb, false, false, false, false, false, false, false, false, fals